/**
 * Optional human touches on top of the auto-generated media list.
 *
 * The generator only knows dates, so captions default to things like
 * "17 July 2026". Add nicer wording here — keys are the `id` values you can see
 * in `data/media.generated.ts`, and nothing breaks if a key is missing.
 */

/** id → caption shown under a photo in the lightbox and on hover. */
export const photoCaptions: Record<string, string> = {
  // "photo-1000025855-jpg": "First day home 💙",
};

/** id → title shown on a video card. */
export const videoTitles: Record<string, string> = {
  // "video-vid20260413162708": "Crawling at full speed",
};

/** "2026-03" → a short line describing that month. */
export const monthNotes: Record<string, string> = {
  // "2025-08": "The week you arrived and changed everything.",
};
